// LSH occupancy → front-desk morning board.
const r = $input.first().json;
const rooms = Array.isArray(r.data) ? r.data : (Array.isArray(r) ? r : []);
const lines = rooms.map(x => 'Room ' + x.room + (x.guest ? (' — ' + x.guest) : '') + (x.nights ? (', ' + x.nights + 'n') : ''));
const summary = '🏨 Front desk ' + new Date().toISOString().slice(0,10) + ': ' + rooms.length + ' room(s) occupied' + (lines.length ? (' | ' + lines.join(' · ')) : '');
return [{ json: { date: new Date().toISOString().slice(0,10), occupied: rooms.length, rooms, summary } }];
